import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdirSync, rmSync, symlinkSync } from 'node:fs';
import { runPlugin, REFUSED, pluginPath } from '../src/launcher.mjs';

const root = process.cwd();

test('a working plugin runs and its exit code is 0', () => {
  assert.equal(runPlugin(root, 'hello'), 0);
});

test("a failing plugin's own exit code is propagated", () => {
  assert.equal(runPlugin(root, 'fails'), 7);
});

test('a plugin that does not exist is refused', () => {
  assert.equal(runPlugin(root, 'absent'), REFUSED);
});

test('a plugin that does not exist is refused with a message naming it', () => {
  let stderr = '';
  const original = process.stderr.write.bind(process.stderr);
  process.stderr.write = (chunk) => {
    stderr += chunk;
    return true;
  };
  try {
    runPlugin(root, 'absent');
  } finally {
    process.stderr.write = original;
  }
  assert.match(stderr, /absent/);
});

test('a plugin path that is a directory is refused, not shelled out to', () => {
  const name = 'dir-plugin';
  const path = pluginPath(root, name);
  mkdirSync(path);
  try {
    assert.equal(runPlugin(root, name), REFUSED);
  } finally {
    rmSync(path, { recursive: true, force: true });
  }
});

test('a plugin path that is a broken symlink is refused', () => {
  const name = 'broken-link-plugin';
  const path = pluginPath(root, name);
  symlinkSync(join_nonexistent_target(), path);
  try {
    assert.equal(runPlugin(root, name), REFUSED);
  } finally {
    rmSync(path, { force: true });
  }
});

function join_nonexistent_target() {
  return '/nonexistent/target-for-launcher-test.sh';
}

